// Stellar Oracle service worker (#361).
//
// Hand-written rather than generated by a build plugin, so no new build
// dependency is required. Registered only in production builds — see
// src/utils/registerServiceWorker.ts. Provides:
//   - An app-shell + offline-fallback cache for offline use.
//   - A cache-first runtime strategy for same-origin static assets.
//   - A controlled update flow: new versions install and wait until the
//     page explicitly asks them to activate (see PwaUpdateBanner.tsx),
//     so users are never silently switched to a new build mid-session.

// Stamped by the production build (vite.config.ts, releaseManifestPlugin) from the
// emitted asset list, so the cache is keyed to the files this worker ships and
// old caches are pruned when they change. Unbuilt copies keep the placeholder and
// fall back to the registration's ?v= build ID.
const RELEASE_VERSION = '__RELEASE_VERSION__'
const SW_VERSION = RELEASE_VERSION.includes('RELEASE_VERSION')
  ? new URL(self.location.href).searchParams.get('v') || 'development'
  : RELEASE_VERSION
const CACHE_PREFIX = 'stellar-oracle-shell-'
const CACHE_VERSION = `${CACHE_PREFIX}${SW_VERSION}`
const SCOPE_URL = new URL('.', self.location.href)
const OFFLINE_URL = new URL('offline.html', SCOPE_URL).href
// offline.html's stylesheet and script are same-origin files (the CSP forbids
// inline ones), so they must be precached too — an offline document that still
// needs the network for its CSS and retry handler is not an offline document.
const OFFLINE_ASSETS = ['offline.css', 'offline.js'].map((file) => new URL(file, SCOPE_URL).href)
const SHELL_URLS = [SCOPE_URL.href, OFFLINE_URL, ...OFFLINE_ASSETS]

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE_VERSION).then((cache) => cache.addAll(SHELL_URLS)))
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => {
        const appCaches = keys.filter((key) => key.startsWith(CACHE_PREFIX))
        const previousCaches = appCaches.filter((key) => key !== CACHE_VERSION)
        const staleCaches = previousCaches.slice(0, -1)
        return Promise.all(staleCaches.map((key) => caches.delete(key))).then(() => previousCaches.length > 0)
      })
      .then(async (hasPreviousVersion) => {
        await self.clients.claim()
        if (!hasPreviousVersion) return

        const clients = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' })
        clients.forEach((client) => client.postMessage({ type: 'UPDATE_ACTIVATED', version: SW_VERSION }))
      }),
  )
})

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting()
  }
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigate(request))
    return
  }

  if (new URL(request.url).origin === self.location.origin) {
    event.respondWith(handleAsset(request))
  }
})

async function handleNavigate(request) {
  try {
    return await fetch(request)
  } catch {
    const cache = await caches.open(CACHE_VERSION)
    const offline = await cache.match(OFFLINE_URL)
    return offline || Response.error()
  }
}

async function handleAsset(request) {
  const cacheNames = (await caches.keys()).filter((name) => name.startsWith(CACHE_PREFIX)).reverse()
  for (const cacheName of cacheNames) {
    const cached = await (await caches.open(cacheName)).match(request)
    if (cached) return cached
  }

  try {
    const response = await fetch(request)
    if (response.ok) {
      await (await caches.open(CACHE_VERSION)).put(request, response.clone())
    }
    return response
  } catch {
    return Response.error()
  }
}
